"use client";

import "../../styles/teum-base.css";
import "../../styles/components/checkbox.css";
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";
import { Check, Minus } from "@phosphor-icons/react";
import { useId } from "react";
import { cn } from "../../lib/cn";

export type CheckboxProps = CheckboxPrimitive.Root.Props & {
  label?: string;
  description?: string;
};

export function Checkbox({ className, label, description, id: providedId, "aria-describedby": ariaDescribedBy, "aria-labelledby": ariaLabelledBy, ...props }: CheckboxProps) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const labelId = label ? `${id}-label` : undefined;
  const descriptionId = description ? `${id}-description` : undefined;
  const describedBy = [ariaDescribedBy, descriptionId].filter(Boolean).join(" ") || undefined;
  return (
    <div className="teum-choice-row">
      <CheckboxPrimitive.Root id={id} className={cn("teum-checkbox", className)} aria-labelledby={ariaLabelledBy ?? labelId} aria-describedby={describedBy} {...props}>
        <CheckboxPrimitive.Indicator className="teum-checkbox__indicator">
          <Check className="teum-checkbox__check" weight="bold" />
          <Minus className="teum-checkbox__mixed" weight="bold" />
        </CheckboxPrimitive.Indicator>
      </CheckboxPrimitive.Root>
      {label && (
        <label htmlFor={id} className="teum-choice-copy">
          <span id={labelId}>{label}</span>
          {description && <small id={descriptionId}>{description}</small>}
        </label>
      )}
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-choice-row { display: flex; align-items: flex-start; gap: 9px; }

.teum-choice-copy { display: grid; gap: 3px; color: var(--teum-ink); font-size: 13.5px; cursor: pointer; }

.teum-choice-copy small { color: var(--teum-ink-tertiary); font-size: 11.5px; font-weight: 400; line-height: 1.45; }

.teum-checkbox { position: relative; display: grid; width: 16px; height: 16px; flex: none; margin-top: 1px; padding: 0; place-items: center; border: 1px solid var(--teum-border-strong); border-radius: 4px; background: var(--teum-surface); color: var(--teum-on-inverse); cursor: pointer; transition: background var(--teum-hover-duration), border-color var(--teum-hover-duration), transform var(--teum-press-duration) var(--teum-ease-out); }

.teum-checkbox::after { position: absolute; inset: -8px; content: ""; }

.teum-checkbox[data-checked] { border-color: var(--teum-inverse); background: var(--teum-inverse); color: var(--teum-on-inverse); }

.teum-checkbox[data-indeterminate] { border-color: var(--teum-inverse); background: var(--teum-inverse); color: var(--teum-on-inverse); }

.teum-checkbox[data-disabled] { opacity: 0.42; cursor: not-allowed; }

.teum-checkbox:active:not([data-disabled]) { transform: scale(0.96); }

.teum-checkbox__indicator { display: grid; place-items: center; }

.teum-checkbox__indicator svg { width: 11px; height: 11px; }

.teum-checkbox__mixed { display: none; }

.teum-checkbox[data-indeterminate] .teum-checkbox__check { display: none; }

.teum-checkbox[data-indeterminate] .teum-checkbox__mixed { display: block; }

.teum-choice-row:has([data-disabled]) .teum-choice-copy { opacity: 0.48; cursor: not-allowed; }

@media (forced-colors: active) {
.teum-checkbox { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }

.teum-checkbox[data-checked],
.teum-checkbox[data-indeterminate] { background: Highlight; color: HighlightText; }
}

:root[data-theme="dark"] .teum-checkbox[data-checked],
:root[data-theme="dark"] .teum-checkbox[data-indeterminate] { box-shadow: none; }

.teum-checkbox__indicator {
  opacity: 1;
  transform: scale(1);
  transition: opacity 140ms var(--teum-ease-out), transform 140ms var(--teum-ease-out);
}

@starting-style {
.teum-checkbox__indicator {
    opacity: 0;
    transform: scale(.72);
  }
}

@media (prefers-reduced-motion: reduce) {
.teum-checkbox:active:not([data-disabled]) { transform: none; }

.teum-checkbox__indicator { transition-duration: 0.01ms; }
}
}
